def display_indices(graph, existing):
    indices = list(existing)
    if graph.manifest.get('sha256') == MORPHOLOGY_CONNECTOME:
        lookup = {int(ident): i for i, ident in enumerate(graph.ids)}
        indices.extend(lookup[ident] for ident in MORPHOLOGY_IDS if ident in lookup)
    return list(dict.fromkeys(indices))


def population_summary(rates):
    rates = np.asarray(rates)
    return {'neuron_count': int(rates.size), 'mean_hz': float(rates.mean()) if rates.size else 0.,
            'active_count': int(np.count_nonzero(rates > 1)),
            'above_400hz_count': int(np.count_nonzero(rates > 400)),
            'definition': 'active > 1 Hz; high > 400 Hz; full retained graph, not spatial ROI averages'}
